sources.content:
const int SENSOR = A0;
const int LED = 9;

void setup() {
  Serial.begin(9600);
  pinMode(LED, OUTPUT);
}

void loop() {
  int light = analogRead(SENSOR);  // brighter reads higher
  Serial.println(light);

  if (light < 400) {
    digitalWrite(LED, HIGH);  // too dark: light the LED
  } else {
    digitalWrite(LED, LOW);
  }
  delay(100);
}
